package com.aether.gateway.cache;

import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

public class SemanticCacheService {

    private static final double DEFAULT_THRESHOLD = 0.94;
    private static final int MAX_CANDIDATES = 20;
    private static final Duration DEFAULT_TTL = Duration.ofHours(6);

    private final EmbeddingClient embeddingClient;
    private final VectorStore vectorStore;
    private final EntityGuard entityGuard;
    private final CacheMetrics metrics;
    private final ConcurrentHashMap<String, CacheEntry> localHotCache = new ConcurrentHashMap<>();
    private final AtomicLong hitCount = new AtomicLong();
    private final AtomicLong missCount = new AtomicLong();
    private final AtomicLong guardRejectionCount = new AtomicLong();

    private volatile double similarityThreshold = DEFAULT_THRESHOLD;

    public SemanticCacheService(EmbeddingClient embeddingClient,
                                 VectorStore vectorStore,
                                 EntityGuard entityGuard,
                                 CacheMetrics metrics) {
        this.embeddingClient = embeddingClient;
        this.vectorStore = vectorStore;
        this.entityGuard = entityGuard;
        this.metrics = metrics;
    }

    public CacheLookupResult lookup(String prompt, String modelId) {
        Instant start = Instant.now();
        float[] embedding = embeddingClient.embed(prompt);

        List<VectorMatch> candidates = vectorStore.query(embedding, modelId, MAX_CANDIDATES);
        if (candidates.isEmpty()) {
            recordMiss(start);
            return CacheLookupResult.miss();
        }

        VectorMatch best = candidates.get(0);
        if (best.similarity() < similarityThreshold) {
            recordMiss(start);
            return CacheLookupResult.miss();
        }

        boolean guardPassed = entityGuard.check(prompt, best.originalPrompt());
        if (!guardPassed) {
            guardRejectionCount.incrementAndGet();
            metrics.recordGuardRejection(best.similarity());
            recordMiss(start);
            return CacheLookupResult.miss();
        }

        hitCount.incrementAndGet();
        metrics.recordHit(best.similarity(), Duration.between(start, Instant.now()));
        return CacheLookupResult.hit(best.response(), best.similarity(), best.entryId());
    }

    public void store(String prompt, String response, String modelId, int promptTokens, int responseTokens) {
        float[] embedding = embeddingClient.embed(prompt);
        String entryId = UUID.randomUUID().toString();

        CacheEntry entry = new CacheEntry(
                entryId,
                prompt,
                response,
                modelId,
                Instant.now(),
                Instant.now().plus(DEFAULT_TTL),
                promptTokens,
                responseTokens
        );

        vectorStore.insert(entryId, embedding, entry);
        localHotCache.put(entryId, entry);
        metrics.recordStore(promptTokens, responseTokens);
    }

    public void invalidate(String entryId) {
        vectorStore.delete(entryId);
        localHotCache.remove(entryId);
        metrics.recordInvalidation();
    }

    public void invalidateByModel(String modelId) {
        vectorStore.deleteByModel(modelId);
        localHotCache.entrySet().removeIf(e -> e.getValue().modelId().equals(modelId));
        metrics.recordBulkInvalidation(modelId);
    }

    public void setSimilarityThreshold(double threshold) {
        if (threshold < 0.0 || threshold > 1.0) {
            throw new IllegalArgumentException("Threshold must be between 0.0 and 1.0, got: " + threshold);
        }
        this.similarityThreshold = threshold;
    }

    public double getSimilarityThreshold() {
        return similarityThreshold;
    }

    public CacheStats getStats() {
        long hits = hitCount.get();
        long misses = missCount.get();
        long total = hits + misses;
        double hitRate = total == 0 ? 0.0 : (double) hits / total;
        return new CacheStats(hits, misses, guardRejectionCount.get(), hitRate, localHotCache.size());
    }

    public void evictExpired() {
        Instant now = Instant.now();
        List<String> expired = localHotCache.entrySet().stream()
                .filter(e -> e.getValue().expiresAt().isBefore(now))
                .map(java.util.Map.Entry::getKey)
                .toList();
        for (String id : expired) {
            invalidate(id);
        }
    }

    private void recordMiss(Instant start) {
        missCount.incrementAndGet();
        metrics.recordMiss(Duration.between(start, Instant.now()));
    }

    public Optional<CacheEntry> getLocalEntry(String entryId) {
        return Optional.ofNullable(localHotCache.get(entryId));
    }

    public interface EmbeddingClient {
        float[] embed(String text);
    }

    public interface VectorStore {
        List<VectorMatch> query(float[] embedding, String modelId, int limit);
        void insert(String entryId, float[] embedding, CacheEntry entry);
        void delete(String entryId);
        void deleteByModel(String modelId);
    }

    public interface EntityGuard {
        boolean check(String incomingPrompt, String cachedPrompt);
    }

    public interface CacheMetrics {
        void recordHit(double similarity, Duration lookupTime);
        void recordMiss(Duration lookupTime);
        void recordGuardRejection(double similarity);
        void recordStore(int promptTokens, int responseTokens);
        void recordInvalidation();
        void recordBulkInvalidation(String modelId);
    }

    public record VectorMatch(String entryId, double similarity, String originalPrompt, String response) {}

    public record CacheEntry(
            String entryId,
            String prompt,
            String response,
            String modelId,
            Instant createdAt,
            Instant expiresAt,
            int promptTokens,
            int responseTokens
    ) {}

    public record CacheLookupResult(boolean hit, String response, double similarity, String entryId) {
        static CacheLookupResult hit(String response, double similarity, String entryId) {
            return new CacheLookupResult(true, response, similarity, entryId);
        }
        static CacheLookupResult miss() {
            return new CacheLookupResult(false, null, 0.0, null);
        }
    }

    public record CacheStats(long hits, long misses, long guardRejections, double hitRate, int localCacheSize) {}
}

class DefaultEntityGuard implements SemanticCacheService.EntityGuard {

    private static final java.util.regex.Pattern NUMBER_PATTERN = java.util.regex.Pattern.compile("\\b\\d+(?:[.,]\\d+)?\\b");
    private static final java.util.Set<String> NEGATION_WORDS = java.util.Set.of("not", "no", "never", "n't", "without");

    @Override
    public boolean check(String incomingPrompt, String cachedPrompt) {
        List<String> incomingNumbers = extractNumbers(incomingPrompt);
        List<String> cachedNumbers = extractNumbers(cachedPrompt);
        if (!incomingNumbers.equals(cachedNumbers)) {
            return false;
        }

        boolean incomingNegated = containsNegation(incomingPrompt);
        boolean cachedNegated = containsNegation(cachedPrompt);
        if (incomingNegated != cachedNegated) {
            return false;
        }

        return true;
    }

    private List<String> extractNumbers(String text) {
        return NUMBER_PATTERN.matcher(text).results()
                .map(java.util.regex.MatchResult::group)
                .toList();
    }

    private boolean containsNegation(String text) {
        String lower = text.toLowerCase();
        for (String word : NEGATION_WORDS) {
            if (lower.contains(" " + word + " ") || lower.endsWith(" " + word)) {
                return true;
            }
        }
        return false;
    }
}

class TokenBucketRateLimiter {

    private final long capacity;
    private final long refillTokensPerSecond;
    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    TokenBucketRateLimiter(long capacity, long refillTokensPerSecond) {
        this.capacity = capacity;
        this.refillTokensPerSecond = refillTokensPerSecond;
    }

    boolean tryConsume(String key, long tokens) {
        Bucket bucket = buckets.computeIfAbsent(key, k -> new Bucket(capacity, Instant.now()));
        synchronized (bucket) {
            refill(bucket);
            if (bucket.tokens >= tokens) {
                bucket.tokens -= tokens;
                return true;
            }
            return false;
        }
    }

    private void refill(Bucket bucket) {
        Instant now = Instant.now();
        long elapsedSeconds = Duration.between(bucket.lastRefill, now).toSeconds();
        if (elapsedSeconds <= 0) {
            return;
        }
        long refillAmount = elapsedSeconds * refillTokensPerSecond;
        bucket.tokens = Math.min(capacity, bucket.tokens + refillAmount);
        bucket.lastRefill = now;
    }

    private static class Bucket {
        long tokens;
        Instant lastRefill;

        Bucket(long tokens, Instant lastRefill) {
            this.tokens = tokens;
            this.lastRefill = lastRefill;
        }
    }
}
